insert into public.finding_rules (code, severity, domain, title, description) values
  ('FW-001', 'critical', 'access', 'Administración expuesta en interfaz WAN', 'La administración por HTTPS o SSH responde en una interfaz conectada a internet. Cualquiera puede intentar autenticarse contra el equipo que protege la red.'),
  ('FW-002', 'high', 'access', 'Administrador sin segundo factor', 'Una cuenta administrativa entra solo con contraseña. Una contraseña filtrada basta para reconfigurar el firewall.'),
  ('FW-003', 'high', 'access', 'Administrador sin restricción de hosts de confianza', 'La cuenta puede autenticarse desde cualquier dirección. Limitarla a las IP de administración reduce la superficie de ataque sin costo.'),
  ('FW-004', 'medium', 'access', 'Más de dos administradores con perfil total', 'Varias cuentas con permisos completos diluyen la trazabilidad de los cambios y amplían el impacto de una credencial comprometida.'),
  ('FW-005', 'high', 'maintenance', 'Firmware fuera de soporte o con vulnerabilidad conocida', 'La versión instalada ya no recibe parches o tiene un CVE publicado con explotación conocida.'),
  ('FW-006', 'critical', 'policy', 'Política de origen y destino abiertos con todos los servicios', 'Una regla permite cualquier origen hacia cualquier destino en cualquier puerto. El firewall deja de filtrar en ese punto.'),
  ('FW-007', 'medium', 'policy', 'Políticas sin tráfico en 90 días', 'Reglas que nadie usa siguen abiertas. Cada una es una puerta que hay que revisar en la próxima auditoría.'),
  ('FW-008', 'medium', 'logging', 'Políticas permitidas sin registro', 'El tráfico que estas reglas permiten no queda en ningún log: no hay forma de reconstruir un incidente que pasó por ahí.'),
  ('FW-009', 'medium', 'policy', 'Políticas de salida sin inspección', 'Tráfico saliente sin IPS, antivirus, filtrado web ni control de aplicaciones. Las licencias están pagadas y sin usar.'),
  ('FW-010', 'high', 'policy', 'NAT entrante hacia administración o bases de datos', 'Hay un puerto publicado desde internet hacia un servicio de administración o una base de datos interna.'),
  ('FW-011', 'high', 'vpn', 'VPN de acceso remoto sin segundo factor', 'Los usuarios entran a la red interna con usuario y contraseña. Es el vector de ransomware más común en PYMES.'),
  ('FW-012', 'medium', 'crypto', 'VPN con cifrado obsoleto', 'TLS por debajo de 1.2, o IPsec con IKEv1, DES/3DES o grupos Diffie-Hellman de 1024 bits o menos.'),
  ('FW-013', 'medium', 'crypto', 'Certificado por vencer o autofirmado en portal público', 'El portal que ven los usuarios presenta un certificado que el navegador no valida, o que caduca pronto.'),
  ('FW-014', 'low', 'access', 'SNMP v1/v2c con comunidad por defecto', 'La comunidad de solo lectura sigue en el valor de fábrica y viaja sin cifrar. Expone el inventario de la red.'),
  ('FW-015', 'low', 'logging', 'Sin NTP o con desfase de reloj', 'El reloj del firewall se aparta más de 60 segundos. Los tiempos de los logs dejan de servir como evidencia.'),
  ('FW-016', 'medium', 'maintenance', 'Licencias de seguridad vencidas o por vencer', 'Las suscripciones de IPS, antivirus o filtrado web están vencidas o caducan pronto: las firmas dejan de actualizarse.'),
  ('FW-017', 'low', 'logging', 'Sin destino de syslog adicional al colector', 'Solo hay una copia de los registros. Los marcos que exigen retención larga piden un segundo destino.'),
  ('FW-018', 'medium', 'maintenance', 'Alta disponibilidad degradada', 'El clúster está configurado pero uno de los miembros no responde o no sincroniza. La redundancia no existe hoy.'),
  ('FW-019', 'medium', 'logging', 'Pérdida de eventos en el colector', 'Más del 1 % de las líneas de syslog se descartan. Los conteos del informe de actividad quedan por debajo de la realidad.'),
  ('FW-020', 'high', 'policy', 'Tráfico permitido hacia países de alto riesgo', 'Hay tráfico saliente autorizado hacia regiones sin relación con la operación del negocio y sin justificación registrada.'),
  ('OP-001', 'medium', 'policy', 'Sin revisión de reglas en los últimos seis meses', 'No se ha generado ni aprobado un informe de hardening en el período que exige el marco seleccionado.'),
  ('OP-002', 'medium', 'logging', 'Eventos críticos sin tratamiento en siete días', 'Hay alertas de alta severidad que nadie marcó como atendidas. Un evento sin cierre no es evidencia de control.'),
  ('OP-003', 'high', 'logging', 'Retención de registros inferior a la exigida', 'La retención combinada de bóveda local y agregados en la nube no alcanza lo que pide el marco activo.'),
  ('OP-004', 'low', 'logging', 'Cambios de configuración sin actor identificado', 'Hubo cambios cuya autoría no aparece en el syslog de administración: no se puede saber quién los hizo.')
insert into public.frameworks (code, name, version, log_retention_days, total_controls, scope_note) values
  ('iso27001', 'ISO/IEC 27001:2022 Anexo A', '2022', 0, 93, 'EventReport aporta evidencia técnica del perímetro para tu SGSI. No sustituye la auditoría ni certifica el sistema de gestión.'),
  ('cis_v8', 'CIS Controls v8 (IG1/IG2)', '8.0', 0, 153, 'Estado por salvaguarda, más los ítems del CIS Benchmark de la marca cuando existe para tu equipo.'),
  ('pci_dss', 'PCI DSS v4.0.1', '4.0.1', 365, 250, 'Cubre los controles de seguridad de red. La retención de 12 meses del requisito 10.5.1 no se satisface con la bóveda local: hace falta un destino de registros adicional (FW-017).'),
  ('hipaa', 'HIPAA Security Rule (45 CFR 164)', '2013', 2190, 42, 'Evidencia de salvaguardas técnicas de red. HIPAA no es certificable; aplica si procesas datos de salud de entidades cubiertas en Estados Unidos.')
