insert into public.rule_remediations (rule_code, brand, steps) values
  ('FW-001', 'fortigate', array['Entra a Network › Interfaces y abre la interfaz WAN señalada en el hallazgo.','En Administrative Access desmarca HTTPS, SSH y PING.','Si necesitas administrar desde fuera, deja solo HTTPS y agrega las IP de administración en System › Admin › Trusted Hosts.','Confirma por CLI: config system interface, edit <interfaz>, unset allowaccess.']),
  ('FW-011', 'fortigate', array['Crea el servidor de segundo factor en User & Authentication › FortiToken o RADIUS.','Asigna el token a cada usuario del grupo de VPN.','En VPN › SSL-VPN Settings exige el grupo con MFA en Authentication/Portal Mapping.','Prueba con una cuenta antes de cerrar el acceso al resto.']),
  ('FW-006', 'fortigate', array['Abre Policy & Objects › Firewall Policy y localiza la política señalada en el hallazgo.','Reemplaza el origen y el destino any por los grupos de direcciones reales.','Cambia el servicio ALL por los puertos que la aplicación necesita.','Deja la política deshabilitada un día y revisa el contador de aciertos antes de borrarla.']),
  ('FW-009', 'sophos_xg', array['Entra a Rules and policies › Firewall rules y abre la regla señalada en el hallazgo.','En Security features activa IPS, protección web y control de aplicaciones.','Selecciona los perfiles predeterminados de tu política de salida.','Verifica el consumo de CPU la primera hora: la inspección agrega carga.']),
  ('FW-014', 'sophos_xg', array['Ve a Administration › SNMP y elimina la comunidad public.','Crea un usuario SNMPv3 con autenticación SHA y cifrado AES.','Restringe el acceso a la IP del sistema de monitoreo.'])
